package com.lianxibu.site.service.sources;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;import com.lianxibu.site.repository.sources.JdbcSourceContractSnapshots;
import java.time.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.*;
import javax.sql.DataSource;import org.h2.jdbcx.JdbcDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
class SourceContractSnapshotsTest {
 DataSource db;JdbcTemplate jdbc;TransactionTemplate tx;JdbcSourceContractSnapshots store;final Instant now=Instant.parse("2026-01-01T00:10:00Z");
 DataSource source(){var ds=new JdbcDataSource();ds.setURL("jdbc:h2:mem:source-contract-native-"+System.nanoTime()+";MODE=MySQL;DB_CLOSE_DELAY=-1");return ds;}
 @BeforeEach void setup(){db=source();jdbc=new JdbcTemplate(db);jdbc.execute("DROP TABLE IF EXISTS request_receipts");jdbc.execute("DROP TABLE IF EXISTS runtime_settings");String json=db instanceof JdbcDataSource?"CLOB":"JSON",timestamp=db instanceof JdbcDataSource?"TIMESTAMP(6)":"DATETIME(6)";jdbc.execute("CREATE TABLE request_receipts(principal VARCHAR(80),operation VARCHAR(32),request_key VARCHAR(128),request_hash BINARY(32),status_code INT,response_json "+json+",expires_at "+timestamp+",id VARCHAR(64) PRIMARY KEY,receipt_kind VARCHAR(32),actor_id VARCHAR(64),source_id VARCHAR(80),scope VARCHAR(128),key_hash BINARY(32),original_status VARCHAR(32),current_status VARCHAR(32),ack_json "+json+",result_ref_json "+json+",created_at "+timestamp+",revision BIGINT,request_key_raw VARCHAR(128),business_hash BINARY(32),UNIQUE(actor_id,scope,key_hash))");jdbc.execute("CREATE TABLE runtime_settings(setting_key VARCHAR(64) PRIMARY KEY,value_json "+json+" NOT NULL,revision BIGINT NOT NULL,updated_at "+timestamp+" NOT NULL)");tx=new TransactionTemplate(new DataSourceTransactionManager(db));store=new JdbcSourceContractSnapshots(db);}
 SourceContractTelemetry.Parsed value(long sequence,long total,boolean event)throws Exception{var root=(tools.jackson.databind.node.ObjectNode)CanonicalJson.parse(Files.readAllBytes(Path.of("../contracts/source-contract-telemetry-v1.example.json")));root.put("sequence",sequence);root.put("total_failures",total);if(!event)root.putArray("events");return SourceContractTelemetry.parse(CanonicalJson.bytes(root));}
 JdbcSourceContractSnapshots.Receipt save(SourceContractTelemetry.Parsed input,Instant at){return tx.execute(s->store.save("fictional-node",1,input,at));}
 @Test void nativeReceiptAndPointerReplayOriginalTimeWithoutWritingAgain()throws Exception{var input=value(1,1,true);var receipt=save(input,now);assertNotNull(receipt);assertEquals(receipt,save(input,now.plusSeconds(60)));assertEquals(receipt,tx.execute(s->store.latest("fictional-node","fictional-source")));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(1L,jdbc.queryForObject("SELECT revision FROM runtime_settings",Long.class));assertEquals(now,receipt.receivedAt());assertFalse(receipt.toString().contains("fictional-node"));}
 @Test void sameIdentityConflictCounterRollbackOrDroppedLiveEventCannotOverwriteActualFacts()throws Exception{save(value(1,1,true),now);var conflict=value(1,2,true);assertThrows(IllegalStateException.class,()->save(conflict,now));var rollback=value(2,0,false);assertThrows(IllegalStateException.class,()->save(rollback,now));var dropped=value(2,1,false);assertThrows(IllegalStateException.class,()->save(dropped,now));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));}
 @Test void newerSnapshotAdvancesPointerButOriginalReceiptRemainsPermanent()throws Exception{var first=value(1,1,true);var original=save(first,now);var second=save(value(2,1,true),now.plusSeconds(60));assertEquals(second,tx.execute(s->store.latest("fictional-node","fictional-source")));assertEquals(original,tx.execute(s->store.committed("fictional-node",first)));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(2L,jdbc.queryForObject("SELECT revision FROM runtime_settings",Long.class));}
 @Test void damageCapacityAndReadonlyOrMissingTransactionFailClosedWithoutNewReceipt()throws Exception{var input=value(1,1,true);assertThrows(IllegalStateException.class,()->store.latest("fictional-node","fictional-source"));tx.setReadOnly(true);assertThrows(IllegalStateException.class,()->save(input,now));tx.setReadOnly(false);save(input,now);jdbc.update("UPDATE request_receipts SET request_hash=?",new byte[32]);assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest("fictional-node","fictional-source")));jdbc.update("UPDATE runtime_settings SET value_json=?","{\"unknown\":\""+"x".repeat(3000)+"\"}");assertThrows(IllegalStateException.class,()->tx.execute(s->store.latest("fictional-node","fictional-source")));}
 @Test void pointerAndReceiptCommitTogetherOrRollbackTogether()throws Exception{var input=value(1,1,true);assertThrows(IllegalStateException.class,()->tx.execute(s->{store.save("fictional-node",1,input,now);throw new IllegalStateException("fictional abort");}));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM request_receipts",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM runtime_settings",Integer.class));assertNull(tx.execute(s->store.latest("fictional-node","fictional-source")));}
}
